namespace FrameForge.Core;

// Local, allowlisted implementations. No downloaded script is executed.
public static class PerformanceTweaks
{
    const string edge=@"Software\Policies\Microsoft\Edge";
    const string chrome=@"Software\Policies\Google\Chrome";
    const string search=@"SOFTWARE\Policies\Microsoft\Windows\Windows Search";
    const string updates=@"SOFTWARE\Policies\Microsoft\Windows\DeliveryOptimization";
    public static IReadOnlyList<Optimization> Operations {get;}=[
        new("chrome-background","Keep Chrome running after closing","Browser memory","Keeps Chrome apps working after its windows close. Off can free memory; background notifications may stop.","Less idle browser memory","https://chromeenterprise.google/policies/background-mode-enabled/",Risk.Review,ActionKind.Registry,chrome+"|BackgroundModeEnabled","1"),
        new("chrome-memory","Chrome Memory Saver","Browser memory","Releases memory from inactive tabs while Chrome is open. Tabs may reload when you return to them.","More memory for your game","https://chromeenterprise.google/policies/high-efficiency-mode-enabled/",Risk.Review,ActionKind.Registry,chrome+"|HighEfficiencyModeEnabled","1"),
        new("chrome-memory-strong","Stronger Chrome memory savings","Browser memory","Makes Memory Saver release idle tabs sooner. Turn Memory Saver on too; returning tabs may reload more often.","For many open tabs and limited RAM","https://chromeenterprise.google/policies/memory-saver-mode-savings/",Risk.Review,ActionKind.Registry,chrome+"|MemorySaverModeSavings","2"),
        new("edge-sleep","Edge sleeping tabs","Browser memory","Lets idle Edge tabs sleep to use less CPU and RAM. For local/work profiles; personal Microsoft-account profiles ignore this policy.","Less work from inactive tabs","https://learn.microsoft.com/deployedge/microsoft-edge-policies/sleepingtabsenabled",Risk.Review,ActionKind.Registry,edge+"|SleepingTabsEnabled","1"),
        new("edge-sleep-sooner","Let Edge tabs sleep sooner","Browser memory","Uses a five-minute idle timer. Needs sleeping tabs and a local/work Edge profile; personal Microsoft-account profiles ignore this policy.","Release unused tab memory sooner","https://learn.microsoft.com/deployedge/microsoft-edge-policies/sleepingtabstimeout",Risk.Review,ActionKind.Registry,edge+"|SleepingTabsTimeout","300"),
        new("widgets","Windows Widgets","Background work","Allows the Windows 11 news and Widgets panel. Off blocks this optional experience; sign out to finish the change.","Less optional web-content activity","https://learn.microsoft.com/windows/client-management/mdm/policy-csp-newsandinterests#allownewsandinterests",Risk.Review,ActionKind.MachineRegistry,@"SOFTWARE\Policies\Microsoft\Dsh|AllowNewsAndInterests","1",Admin:true,Restart:true,MinBuild:22000),
        new("search-backoff","Let indexing slow down when busy","Background work","Lets Windows search indexing back off when your PC is busy. Helps if a previous tweak forced full-speed indexing.","Less competing indexing work","https://learn.microsoft.com/windows/client-management/mdm/policy-csp-search#disablebackoff",Risk.Review,ActionKind.MachineRegistry,search+"|DisableBackoff","0",Admin:true),
        new("update-background-limit","Limit background update downloads","Downloads","Limits background Microsoft update downloads to 10% of measured bandwidth. Updates take longer; this does not cap every app.","Less download competition while playing","https://learn.microsoft.com/windows/client-management/mdm/policy-csp-deliveryoptimization#dopercentagemaxbackgroundbandwidth",Risk.Review,ActionKind.MachineRegistry,updates+"|DOPercentageMaxBackgroundBandwidth","10",Admin:true),
        new("update-foreground-limit","Limit manual update downloads","Downloads","Limits Microsoft downloads you start to 25% of measured bandwidth. Installs take longer; game-launcher downloads are unaffected.","Only useful during competing downloads","https://learn.microsoft.com/windows/client-management/mdm/policy-csp-deliveryoptimization#dopercentagemaxforegroundbandwidth",Risk.Review,ActionKind.MachineRegistry,updates+"|DOPercentageMaxForegroundBandwidth","25",Admin:true),
        new("cpu-ac-limit","Allow full CPU speed when plugged in","Power checks","Removes a CPU speed cap in the current power plan. Helps only if it was capped; can increase heat and fan noise.","Fix an existing plugged-in CPU limit","https://learn.microsoft.com/windows-hardware/customize/power-settings/options-for-perf-state-engine-maxperformance",Risk.Experimental,ActionKind.PowerSetting,"cpu-ac-limit"),
        new("wifi-ac-power","Try full Wi-Fi power when plugged in","Power checks","Asks the current power plan to favour Wi-Fi performance. Test only for Wi-Fi spikes; drivers may ignore this setting.","Compare Wi-Fi power-saving delays","https://www.intel.com/content/www/us/en/support/articles/000046272/wireless/legacy-intel-wireless-products.html",Risk.Experimental,ActionKind.PowerSetting,"wifi-ac-power")
    ];
    public static IReadOnlyList<TweakDefinition> Definitions {get;}=[
        new("chrome-background","Browser memory","1","0",Note:"Close Chrome normally. Background notifications can stop. Check chrome://policy; managed PCs may override this.",AllowedValues:["0","1"]),
        new("chrome-memory","Browser memory","1","0",Note:"Chrome 108+. Check HighEfficiencyModeEnabled in chrome://policy. Some active tabs are exempt.",AllowedValues:["0","1"]),
        new("chrome-memory-strong","Browser memory","2","1",Note:"Chrome 126+. Off uses balanced savings. Enable Chrome Memory Saver separately. Check chrome://policy.",AllowedValues:["0","1","2"]),
        new("edge-sleep","Browser memory","1","0",Note:"Edge 88+. These policies do not apply to profiles signed into a personal Microsoft account. Check edge://policy. The default is usually already On.",AllowedValues:["0","1"]),
        new("edge-sleep-sooner","Browser memory","300","900",Note:"On: 5 minutes. Off: 15 minutes. Sleeping tabs must be on. Personal Microsoft-account profiles do not accept this policy. Check edge://policy.",AllowedValues:["30","300","900","1800","3600","7200","10800","21600","43200"]),
        new("widgets","Background work","1","0",Note:"Windows 11 Pro/Enterprise/Education policy. Sign out and back in. Shared runtimes are kept.",AllowedValues:["0","1"]),
        new("search-backoff","Background work","0","1",Note:"On restores normal backoff. Off forces full-speed indexing and can hurt performance. Most PCs already use backoff. Search stays enabled.",AllowedValues:["0","1"]),
        new("update-background-limit","Downloads","10","0",Note:"On: 10%. Off: adaptive bandwidth. Local-LAN peers and other apps may be outside this limit. Absolute/hourly policies take precedence. Updates stay enabled.",Minimum:0,Maximum:100),
        new("update-foreground-limit","Downloads","25","0",Note:"On: 25%. Off: adaptive bandwidth. Local-LAN peers and other apps may be outside this limit. Absolute/hourly policies take precedence. Updates stay enabled.",Minimum:0,Maximum:100)
    ];
    public static bool Relevant(Optimization operation)=>FeatureToggles.Supports(operation)&&(operation.Id is "game-mode" or "game-recording"||TweakDefinitions.Get(operation).Group is "Low-end PC" or "Browser memory" or "Background work" or "Downloads");
}
